      box.append(
        note(
          "Not checked yet: claims are checked a few minutes before they're said.",
        ),
        checkButton(claim, "Check now"),
      );
      break;
    case "checking":
      box.append(note("Checking against web sources…"));
      break;
    case "failed":
      box.append(
        note(`Couldn't check: ${claim.check.error}`),
